// Fonction pour obtenir les comptes par classe
export function getAccountsByClass(classId: string): Account[] {
  const classInfo = ACCOUNT_CLASSES.find(c => c.id === classId)
  if (!classInfo) return []

  return ALL_ACCOUNTS.filter(account => {
    const code = parseInt(account.code)
    return code >= classInfo.range[0] && code <= classInfo.range[1]
  })
}

// Fonction pour compter les comptes actifs par classe
export function countActiveAccountsByClass(classId: string): number {
  return getAccountsByClass(classId).filter(a => a.active).length
}
